{"type": "file", "encoding": "utf-8", "name": "zombies-game-cdk-stack.ts", "path": "zombies-game-cdk/lib/zombies-game-cdk-stack.ts", "size": 11086, "sha": "bd3f3c4153507a73c907cef6f810554da29d598b", "content": "import * as path from "path";
import { Construct } from "constructs";

import * as cdk from "aws-cdk-lib";
import * as ec2 from "aws-cdk-lib/aws-ec2";
import * as ecs from "aws-cdk-lib/aws-ecs";
import * as s3 from "aws-cdk-lib/aws-s3";
import * as elbv2 from "aws-cdk-lib/aws-elasticloadbalancingv2";
import * as secretsmanager from "aws-cdk-lib/aws-secretsmanager";
import * as logs from "aws-cdk-lib/aws-logs";
import * as ecs_patterns from "aws-cdk-lib/aws-ecs-patterns";
import * as ecr_assets from "aws-cdk-lib/aws-ecr-assets";
import * as servicediscovery from "aws-cdk-lib/aws-servicediscovery";
import * as cloudwatch from "aws-cdk-lib/aws-cloudwatch";

import { Database } from "./constructs/database";
import { APP_PREFIX, domain, kebabCase } from "./constructs/util";

export interface ZombiesGameCdkStackProps extends cdk.StackProps {
  production: boolean;
  tokenIssuerEndpoint: string;
  certificateArn: string;
  googleCredentials: string;
  nakamaBaseUrl: string;
  nakamaHttpKey: string;
}

export class ZombiesGameCdkStack extends cdk.Stack {
  public readonly vpc: ec2.Vpc;
  public readonly database: Database;

  constructor(scope: Construct, id: string, props: ZombiesGameCdkStackProps) {
    super(scope, id, props);

    const subdomain = props.production ? "prod-backend" : "dev-backend";
    const domainName = `${subdomain}.${domain}`;

    // Bucket for logging ELB and VPC access
    const loggingBucket = new s3.Bucket(this, `${APP_PREFIX}LoggingBucket`, {
      enforceSSL: true,
      blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
      encryption: s3.BucketEncryption.S3_MANAGED,
      serverAccessLogsPrefix: `${kebabCase(
        APP_PREFIX
      )}-logging-bucket-access-logs`,
    });

    // VPC for our Fargate service
    const vpc = new ec2.Vpc(this, `${APP_PREFIX}Vpc`, { maxAzs: 3 });
    this.vpc = vpc;

    // Create a database for the backend
    const db = new Database(this, `${APP_PREFIX}Database`, {
      vpc,
      production: props.production,
    });
    this.database = db;

    // enable flow logs for the VPC
    vpc.addFlowLog(`${APP_PREFIX}VPCFlowLogs`, {
      destination: ec2.FlowLogDestination.toS3(
        loggingBucket,
        `${kebabCase(APP_PREFIX)}--vpc-flow-logs`
      ),
      trafficType: ec2.FlowLogTrafficType.REJECT,
    });

    // Secret for SECRET_KEY_BASE
    const secretKeyBaseSecret = new secretsmanager.Secret(
      this,
      `${APP_PREFIX}SecretKeyBaseSecret`,
      {
        generateSecretString: {
          passwordLength: 64,
          excludeCharacters: '/@"',
          includeSpace: false,
        },
      }
    );

    const googleCredentialsSecret = new secretsmanager.Secret(
      this,
      `${APP_PREFIX}GoogleCredentialsSecret`,
      {
        secretStringValue: new cdk.SecretValue(props.googleCredentials),
      }
    );

    // ECS cluster to host the service in the VPC
    const cluster = new ecs.Cluster(this, `${APP_PREFIX}Cluster`, {
      vpc,
      containerInsightsV2: ecs.ContainerInsights.ENABLED,
    });

    // The code that defines your stack goes here
    const containerAsset = new ecr_assets.DockerImageAsset(
      this,
      `${APP_PREFIX}BackendApp`,
      {
        platform: ecr_assets.Platform.LINUX_AMD64,
        directory: path.join(__dirname, "../../."),
      }
    );

    const cpu = props.production ? 1024 : 512;
    const memory = props.production ? 2048 : 1024;

    // create task definition for our Fargate service
    const taskDefinition = new ecs.FargateTaskDefinition(
      this,
      `${APP_PREFIX}TaskDefinition`,
      {
        cpu,
        memoryLimitMiB: memory,
      }
    );

    db.cluster.grantConnect(taskDefinition.taskRole, "postgres");

    // Set cpu and memory for Task definition
    taskDefinition.addContainer(`${APP_PREFIX}Service`, {
      image: ecs.ContainerImage.fromDockerImageAsset(containerAsset),
      // readonlyRootFilesystem: true,
      // Add environment variable with issuer endpoint
      secrets: {
        SECRET_KEY_BASE: ecs.Secret.fromSecretsManager(secretKeyBaseSecret),
        GOOGLE_APPLICATION_CREDENTIALS: ecs.Secret.fromSecretsManager(
          googleCredentialsSecret
        ),
        DB_CREDENTIALS: ecs.Secret.fromSecretsManager(db.adminSecret),
      },
      environment: {
        ENVIRONMENT: props.production ? "production" : "development",
        ISSUER_ENDPOINT: props.tokenIssuerEndpoint,
        PHX_HOST: domainName,
        // Leagues schedule
        // PROD: every monday at 00:00 AM UTC
        // DEV: every 30 minutes
        LEAGUES_SCHEDULE: props.production ? "0 0 * * 1" : "*/30 * * * *",
        // Plague Race event schedule
        // PROD: every day at 00:00 AM UTC
        // DEV: every 2 hours
        PLAGUE_RACE_SCHEDULE: props.production ? "0 0 * * *" : "0 */2 * * *",
        // Endless Monster Mode daily event schedule
        // PROD: every day at 00:00 AM UTC
        // DEV: every 30 minutes
        ENDLESS_MONSTER_DAILY_SCHEDULE: props.production
          ? "0 0 * * *"
          : "*/5 * * * *",
        // Endless Monster Mode weekly event schedule
        // PROD: every monday at 00:00 AM UTC
        // DEV: every hour
        ENDLESS_MONSTER_WEEKLY_SCHEDULE: props.production
          ? "0 0 * * 1"
          : "*/10 * * * *",
        // Boss Arena Mode daily event schedule
        // PROD: every day at 00:00 AM UTC
        // DEV: every 5 minutes
        BOSS_ARENA_DAILY_SCHEDULE: props.production
          ? "0 0 * * *"
          : "*/5 * * * *",
        // Boss Arena Mode weekly event schedule
        // PROD: every monday at 00:00 AM UTC
        // DEV: every 10 minutes
        BOSS_ARENA_WEEKLY_SCHEDULE: props.production
          ? "0 0 * * 1"
          : "*/10 * * * *",
        // Win and Collect event schedule - Group 1 (Monday-Tuesday)
        // PROD: every monday and tuesday at 00:00 AM UTC
        // DEV: every hour at minute 0 for fast testing
        WIN_AND_COLLECT_GROUP_1_SCHEDULE: props.production
          ? "0 0 * * 1,2"
          : "0 * * * *",
        // Win and Collect event schedule - Group 2 (Wednesday-Thursday)
        // PROD: every wednesday and thursday at 00:00 AM UTC
        // DEV: every hour at minute 0 for fast testing
        WIN_AND_COLLECT_GROUP_2_SCHEDULE: props.production
          ? "0 0 * * 3,4"
          : "0 * * * *",
        // Win and Collect event schedule - Group 3 (Friday-Sunday)
        // PROD: every friday, saturday and sunday at 00:00 AM UTC
        // DEV: every hour at minute 0 for fast testing
        WIN_AND_COLLECT_GROUP_3_SCHEDULE: props.production
          ? "0 0 * * 5,6,0"
          : "0 * * * *",
        // Season Pass event schedule
        // PROD: every first day of the month at 00:00 AM UTC
        // DEV: every 30 minutes for testing
        SEASON_PASS_SCHEDULE: props.production ? "0 0 1 * *" : "*/30 * * * *",
        // Daily rewards time constants
        DAILY_CLAIM_COOLDOWN_MINUTES: props.production ? "1440" : "5",
        DAILY_STREAK_RESET_MINUTES: props.production ? "2880" : "240",
        // Import rewards schedule
        // PROD: every hour
        // DEV: every 15 minutes (handled in dev.exs)
        IMPORT_REWARDS_SCHEDULE: props.production
          ? "*/5 * * * *"
          : "*/5 * * * *",
        // Zombie Lane sheet name
        // PROD: production sheet
        // DEV: dev sheet with (DEV) prefix
        ZOMBIE_LANE_SHEET_NAME: props.production
          ? "Zombie Lane Trophy Path"
          : "(DEV) Zombie Lane Trophy Path",
        // Zombie Lane sheet range
        ZOMBIE_LANE_RANGE: props.production ? "A1:M300" : "A1:M300",
        NAKAMA_ENABLED: props.production ? "false" : "true",
        NAKAMA_BASE_URL: props.nakamaBaseUrl,
        NAKAMA_HTTP_KEY: props.nakamaHttpKey,
      },
      portMappings: [
        {
          containerPort: 4000,
          protocol: ecs.Protocol.TCP,
        },
      ],
      logging: new ecs.AwsLogDriver({
        streamPrefix: `${APP_PREFIX}Service`,
        logRetention: logs.RetentionDays.ONE_MONTH,
      }),
      // Configure health check for containers
      healthCheck: {
        command: [
          "CMD-SHELL",
          "curl -s -f http://localhost:4000/health || exit 1",
        ],
        interval: cdk.Duration.seconds(5),
        timeout: cdk.Duration.seconds(2),
        retries: 2,
      },
    });

    secretKeyBaseSecret.grantRead(taskDefinition.taskRole);
    googleCredentialsSecret.grantRead(taskDefinition.taskRole);
    cloudwatch.Metric.grantPutMetricData(taskDefinition.taskRole);

    const namespace = new servicediscovery.PrivateDnsNamespace(
      this,
      "cluster-namespace",
      {
        name: "zombies-game-backend.local",
        vpc,
      }
    );

    namespace.createService("cluster-servicediscovery", {
      dnsRecordType: servicediscovery.DnsRecordType.A,
      dnsTtl: cdk.Duration.seconds(10),
    });

    const fargateService =
      new ecs_patterns.ApplicationLoadBalancedFargateService(
        this,
        `${APP_PREFIX}Service`,
        {
          cluster: cluster,
          cpu,
          desiredCount: props.production ? 3 : 2,
          taskDefinition: taskDefinition,
          memoryLimitMiB: memory,
          publicLoadBalancer: true,
          minHealthyPercent: 50,
          // Enable internal command execution for tasks
          // https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-exec.html
          enableExecuteCommand: true,
          loadBalancerName: `${kebabCase(APP_PREFIX)}-lb`,
          cloudMapOptions: {
            name: "zombies-game-backend",
            cloudMapNamespace: namespace,
          },
        }
      );

    fargateService.service.connections.allowFrom(
      ec2.Peer.ipv4(vpc.vpcCidrBlock),
      ec2.Port.tcpRange(0, 65535),
      "Allow internal communication between nodes in the cluster"
    );

    // Configure health check for the load balancer
    fargateService.targetGroup.configureHealthCheck({
      path: "/health",
      interval: cdk.Duration.seconds(5),
      timeout: cdk.Duration.seconds(2),
    });

    // Setup scaling based on CPU load for the service scaling between 3 and 10 Tasks
    // NOTE: Set an appropriate maximum here to match the game's traffic!
    const scalableTaskCount = fargateService.service.autoScaleTaskCount({
      minCapacity: 3,
      maxCapacity: 10,
    });
    scalableTaskCount.scaleOnCpuUtilization("CpuUtilizationScaling", {
      // We're running individual tasks up to 80% CPU utilization before scaling out
      targetUtilizationPercent: 80,
    });

    // Setup HTTPS listener for the load balancer
    fargateService.loadBalancer.addListener("HttpsListener", {
      port: 443,
      certificates: [
        {
          certificateArn: props.certificateArn,
        },
      ],
      defaultAction: elbv2.ListenerAction.forward([fargateService.targetGroup]),
    });

    // enable access logs for the Fargate service ELB
    fargateService.loadBalancer.logAccessLogs(
      loggingBucket,
      `${kebabCase(APP_PREFIX)}-fargate-service-access-logs`
    );
  }
}
